    local source=DevilCompat.Download("https://raw.githubusercontent.com/Razahaider51216/devil-scripthub/main/loader?hub=compat-1")
    local run,err=loadstring(source,"DEVIL HUB / Select current map")assert(run,err)
    return run(...)
end
